begin;

-- Populate onboarding academic structure from a researched 2026 Nigerian-university
-- baseline, then override University of Benin with current first-party UNIBEN data.
--
-- Source precedence:
--   1. Official university source (UNIBEN WAeUP / current first-party pages)
--   2. Researched national baseline snapshot
--
-- University matching is by the catalogue's unique university NAME, not slug.
-- This intentionally supports legacy rows such as UNIBEN whose original slug is
-- "uniben" while the 2026 onboarding catalogue proposes "university-of-benin".
--
-- This migration is intentionally conservative:
-- - no low-confidence fuzzy university matching
-- - no invented departments
-- - acronym-only parentheticals are not treated as departments
-- - programme/degree rows are not inferred here

create temporary table onboarding_academic_structure_seed (
  university_name text not null,
  faculty_name text not null,
  faculty_slug text not null,
  department_name text,
  department_slug text,
  source_url text not null,
  source_kind text not null
) on commit drop;

insert into onboarding_academic_structure_seed (
  university_name,
  faculty_name,
  faculty_slug,
  department_name,
  department_slug,
  source_url,
  source_kind
