delete from onboarding_academic_structure_seed baseline
using onboarding_academic_structure_seed official
where baseline.university_name = official.university_name
  and baseline.faculty_slug = official.faculty_slug
  and coalesce(baseline.department_slug, '') = coalesce(official.department_slug, '')
  and baseline.source_kind <> 'official_university'
  and official.source_kind = 'official_university';

with faculty_seed as (
  select distinct university_name, faculty_name, faculty_slug
  from onboarding_academic_structure_seed
)
update public.faculties faculty
set
  name = seed.faculty_name,
  deleted_at = null,
  updated_at = now()
from faculty_seed seed
join public.universities university
  on university.name = seed.university_name
 and university.deleted_at is null
where faculty.university_id = university.id
  and (
    lower(faculty.name) = lower(seed.faculty_name)
    or faculty.slug = seed.faculty_slug
  );

with faculty_seed as (
  select distinct university_name, faculty_name, faculty_slug
  from onboarding_academic_structure_seed
)
insert into public.faculties (
  id,
  university_id,
  name,
  slug,
  created_at,
  updated_at,
  deleted_at
)
select
  gen_random_uuid(),
  university.id,
  seed.faculty_name,
  seed.faculty_slug,
  now(),
  now(),
  null
from faculty_seed seed
join public.universities university
  on university.name = seed.university_name
 and university.deleted_at is null
where not exists (
  select 1
  from public.faculties existing
  where existing.university_id = university.id
    and (
      lower(existing.name) = lower(seed.faculty_name)
      or existing.slug = seed.faculty_slug
    )
)
on conflict (university_id, slug) do update
set
  name = excluded.name,
  deleted_at = null,
  updated_at = now();

with department_seed as (
  select distinct
    university_name,
    faculty_name,
    faculty_slug,
    department_name,
    department_slug
  from onboarding_academic_structure_seed
  where department_name is not null
    and department_slug is not null
),
mapped as (
  select
    faculty.id as faculty_id,
    seed.department_name,
    seed.department_slug
  from department_seed seed
  join public.universities university
    on university.name = seed.university_name
   and university.deleted_at is null
  join public.faculties faculty
    on faculty.university_id = university.id
   and faculty.deleted_at is null
   and (
     lower(faculty.name) = lower(seed.faculty_name)
     or faculty.slug = seed.faculty_slug
   )
)
update public.departments department
set
  name = mapped.department_name,
  deleted_at = null,
  updated_at = now()
from mapped
where department.faculty_id = mapped.faculty_id
  and (
    lower(department.name) = lower(mapped.department_name)
    or department.slug = mapped.department_slug
  );

with department_seed as (
  select distinct
    university_name,
    faculty_name,
    faculty_slug,
    department_name,
    department_slug
  from onboarding_academic_structure_seed
  where department_name is not null
    and department_slug is not null
),
mapped as (
  select
    faculty.id as faculty_id,
    seed.department_name,
    seed.department_slug
  from department_seed seed
  join public.universities university
    on university.name = seed.university_name
   and university.deleted_at is null
  join public.faculties faculty
    on faculty.university_id = university.id
   and faculty.deleted_at is null
   and (
     lower(faculty.name) = lower(seed.faculty_name)
     or faculty.slug = seed.faculty_slug
   )
)
insert into public.departments (
  id,
  faculty_id,
  name,
  slug,
  created_at,
  updated_at,
  deleted_at
)
select
  gen_random_uuid(),
  mapped.faculty_id,
  mapped.department_name,
  mapped.department_slug,
  now(),
  now(),
  null
from mapped
where not exists (
  select 1
  from public.departments existing
  where existing.faculty_id = mapped.faculty_id
    and (
      lower(existing.name) = lower(mapped.department_name)
      or existing.slug = mapped.department_slug
    )
)
on conflict (faculty_id, slug) do update
set
  name = excluded.name,
  deleted_at = null,
  updated_at = now();

update public.institution_config config
set
  status = case when config.status = 'PREPARING' then 'CATALOGUED' else config.status end,
  updated_at = now()
from (
  select university_name
  from onboarding_academic_structure_seed
  group by university_name
  having count(department_name) > 0
) seed
join public.universities university
  on university.name = seed.university_name
 and university.deleted_at is null
where config.institution_id = university.id;

do $$
declare
  uniben_id uuid;
  faculty_count integer;
  department_count integer;
begin
  select id into uniben_id
  from public.universities
  where name = 'University of Benin'
    and deleted_at is null
  limit 1;

  if uniben_id is null then
    raise exception 'University of Benin is missing from the onboarding catalogue';
  end if;

  select count(*)
  into faculty_count
  from public.faculties
  where university_id = uniben_id
    and deleted_at is null;

  select count(*)
  into department_count
  from public.departments department
  join public.faculties faculty on faculty.id = department.faculty_id
  where faculty.university_id = uniben_id
    and faculty.deleted_at is null
    and department.deleted_at is null;

  if faculty_count < 20 then
    raise exception 'Expected at least 20 active UNIBEN faculty/school units, found %', faculty_count;
  end if;

  if department_count < 100 then
    raise exception 'Expected at least 100 active UNIBEN departments, found %', department_count;
  end if;
end;
$$;

commit;
